'use client';

import { useQuery } from '@tanstack/react-query';
import { api } from '@/lib/api';
import { useAuthStore } from '@/store/auth';
import type { DashboardStats } from '@crm/types';
import { useRouter } from 'next/navigation';
import { Badge } from '@/components/ui/Badge';

const BAR_COLORS = ['#1d4ed8','#2563eb','#3b82f6','#60a5fa','#93c5fd','#bfdbfe','#dbeafe'];

function BarChart({ data }: { data: { label: string; value: number }[] }) {
  const max = Math.max(...data.map(d => d.value), 1);
  return (
    <div className="space-y-2 mt-3">
      {data.map((d, i) => (
        <div key={d.label} className="flex items-center gap-3">
          <div className="text-xs text-gray-500 w-32 flex-shrink-0 text-right">{d.label}</div>
          <div className="flex-1 h-5 bg-gray-100 rounded overflow-hidden">
            <div className="h-full rounded transition-all" style={{ width:`${(d.value/max)*100}%`, background: BAR_COLORS[i % BAR_COLORS.length] }}/>
          </div>
          <div className="text-xs font-semibold text-gray-700 w-10 text-right">{d.value}</div>
        </div>
      ))}
    </div>
  );
}

function StatCard({ label, value, sub, color }: { label: string; value: string|number; sub?: string; color?: string }) {
  return (
    <div className="bg-white border border-gray-200 rounded-xl p-5">
      <div className="text-sm text-gray-400 mb-1">{label}</div>
      <div className="text-3xl font-extrabold tracking-tight mb-0.5" style={{ color: color ?? '#111827' }}>{value}</div>
      {sub && <div className="text-xs text-gray-400">{sub}</div>}
    </div>
  );
}

export default function AnalyticsPage() {
  const user   = useAuthStore(s => s.user);
  const router = useRouter();

  const allowed = user?.role === 'admin' || user?.role === 'supervisor' || user?.role === 'analyst';
  if (!allowed) {
    return (
      <div className="flex flex-col items-center justify-center py-24 text-center">
        <div className="text-5xl mb-4">🔒</div>
        <h2 className="text-xl font-bold mb-2">Недостаточно прав</h2>
        <p className="text-gray-400 text-sm">Аналитика доступна руководителям и аналитикам</p>
      </div>
    );
  }

  const { data: stats, isLoading } = useQuery<DashboardStats>({
    queryKey: ['dashboard'],
    queryFn:  () => api.get('/dashboard'),
  });

  if (isLoading) return <div className="flex items-center justify-center h-64 text-gray-400 text-sm">Загрузка...</div>;
  if (!stats) return null;

  const taskByType = [
    { label:'Звонки',      value: stats.todayTasks?.filter(t => t.type==='call').length ?? 2 },
    { label:'Встречи',     value: stats.todayTasks?.filter(t => t.type==='meeting').length ?? 1 },
    { label:'КП',          value: stats.todayTasks?.filter(t => t.type==='proposal').length ?? 1 },
    { label:'Документы',   value: stats.todayTasks?.filter(t => t.type==='document').length ?? 2 },
    { label:'Анализ',      value: stats.todayTasks?.filter(t => t.type==='analysis').length ?? 0 },
  ];

  const clientsByMgr = stats.myClients
    ? Object.entries(stats.myClients.reduce((acc: Record<string,number>, c) => { acc[c.manager] = (acc[c.manager]||0)+1; return acc; }, {}))
        .map(([label, value]) => ({ label, value: value as number }))
    : [];

  return (
    <div>
      <div className="mb-5">
        <h2 className="text-2xl font-extrabold tracking-tight">Аналитика</h2>
        <p className="text-sm text-gray-400 mt-0.5">Сводные показатели корпоративного блока</p>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-6">
        <StatCard label="Клиентов" value={stats.clientCount} sub="в базе"/>
        <StatCard label="Сделок" value={stats.activeDeals} sub="активных" color="#1d4ed8"/>
        <StatCard label="Задач" value={stats.openTasks} sub="открытых" color="#d97706"/>
        <StatCard label="Pipeline" value={stats.pipelineTotal} sub="млрд сум" color="#059669"/>
      </div>

      <div className="grid lg:grid-cols-2 gap-4 mb-4">
        <div className="bg-white border border-gray-200 rounded-xl p-5">
          <div className="text-sm font-semibold mb-0.5">Задачи по типам</div>
          <div className="text-xs text-gray-400">За текущий период</div>
          <BarChart data={taskByType}/>
        </div>
        <div className="bg-white border border-gray-200 rounded-xl p-5">
          <div className="text-sm font-semibold mb-0.5">Клиенты по менеджерам</div>
          <div className="text-xs text-gray-400">Распределение портфеля</div>
          {clientsByMgr.length > 0 ? <BarChart data={clientsByMgr}/> : <div className="py-6 text-center text-sm text-gray-400">Нет данных</div>}
        </div>
      </div>

      <div className="grid lg:grid-cols-2 gap-4">
        <div className="bg-white border border-gray-200 rounded-xl p-5">
          <div className="text-sm font-semibold mb-3">Последние коммуникации</div>
          <div className="space-y-2">
            {(stats.recentComms ?? []).map((cm, i) => (
              <div key={i} className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-lg bg-gray-100 flex items-center justify-center text-sm flex-shrink-0">
                  {cm.type==='call'?'📞':cm.type==='email'?'✉️':'🤝'}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-medium truncate">{cm.summary}</div>
                  <div className="text-xs text-gray-400">{cm.contact} · {cm.date}</div>
                </div>
              </div>
            ))}
            {!stats.recentComms?.length && <div className="text-sm text-gray-400">Нет коммуникаций</div>}
          </div>
        </div>

        <div className="bg-white border border-gray-200 rounded-xl p-5">
          <div className="text-sm font-semibold mb-3">Топ клиентов</div>
          <div className="space-y-2">
            {(stats.myClients ?? []).map((c, i) => (
              <div key={c.id} className="flex items-center gap-3 cursor-pointer hover:bg-gray-50 -mx-2 px-2 rounded-lg py-1 transition-colors"
                onClick={() => router.push(`/clients/${c.id}`)}>
                <div className="w-6 h-6 rounded-md bg-brand-700 text-white text-[10px] font-bold flex items-center justify-center flex-shrink-0">
                  {i+1}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-medium truncate">{c.name}</div>
                  <div className="text-xs text-gray-400">{c.industry}</div>
                </div>
                <Badge variant={c.status==='active'?'green':c.status==='pending'?'orange':'gray'}>
                  {c.status==='active'?'Актив':c.status==='pending'?'Ожидание':'—'}
                </Badge>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
